sys_script.script:
(function executeRule(current, previous) {
    var s = new GlideRecord('scheduled_import_set');
    if (!s.get('7447f353932fcb107319f2336003d636')) {
        gs.error('DoppelIOCImport: configuration saved, but the "Doppel Alert Import" schedule was not found');
        return;
    }
    var v = current.getValue('connectivity_verified');
    var verified = (v == '1' || v == 'true');
    var minutes = parseInt(current.getValue('import_interval_minutes'), 10) || 60;
    var periodMs = minutes * 60 * 1000;
    var wasActive = s.getValue('active') == '1';
    var isNewConfig = current.operation() == 'insert';
    var changed = false;
    var startingNow = false;
    var startDisplay = '';

    // A new configuration always starts from historical_days: the watermark property ships with the
    // app package and may hold another instance's value.
    if (isNewConfig) {
        new DoppelIOCImport()._setProperty('x_doppe_doppel_t_0.import_watermark', '');
        gs.info('DoppelIOCImport: new configuration | watermark cleared; first import uses historical days');
    }

    // First import about a minute after the connection is verified (or a new configuration is saved),
    // then every <minutes>. The schedule may already be active after install, so a new configuration
    // always resets the start time.
    if (verified && (!wasActive || isNewConfig)) {
        var start = new GlideDateTime();
        start.addSeconds(60);
        s.run_start = start;
        startDisplay = start.getDisplayValue();
        startingNow = true;
        changed = true;
    }
    if (wasActive != verified) {
        s.setValue('active', verified);
        changed = true;
    }
    if (s.run_period.dateNumericValue() != periodMs) {
        s.run_period.setDateNumericValue(periodMs);
        changed = true;
    }
    if (changed) s.update();

    // Log every save so the admin can see what happens next
    if (!verified) {
        gs.info('DoppelIOCImport: configuration saved | scheduled import is inactive until the connection is verified');
    } else if (startingNow) {
        gs.info('DoppelIOCImport: configuration saved | first import starts in about a minute (at ' + startDisplay +
                '), then every ' + minutes + ' minutes');
    } else {
        gs.info('DoppelIOCImport: configuration saved | scheduled import continues every ' + minutes + ' minutes' +
                (changed ? ' (interval updated)' : '') + '; changes apply from the next run');
    }

    if (changed || startingNow) {
        gs.addInfoMessage(!verified
            ? 'Scheduled import is inactive until the connection is verified.'
            : startingNow
                ? 'Configuration saved. The first import starts in about a minute, then runs every ' + minutes + ' minutes.'
                : 'Configuration saved. Scheduled import runs every ' + minutes + ' minutes.');
    }
})(current, previous);
